import json
import re
import sys

COLLECTIONS = {'firmware.Upgrade':'Upgrades', 'firmware.ChassisUpgrade':'ChassisUpgrades', 'firmware.SwitchUpgrade':'SwitchUpgrades'}
def moid(value):
    return isinstance(value, str) and re.fullmatch('[0-9a-fA-F]{24}', value) is not None
def safe_text(value, maximum=500):
    if not isinstance(value, str) or len(value) > maximum or any(ord(c) < 32 for c in value):
        return ''
    if re.search(r'authorization|password|secret|token|api.?key|bearer|https?://', value, re.IGNORECASE):
        return ''
    return value
def envelope(raw, code, succeeded):
    code = int(code)
    if code != 200 or succeeded != 'true':
        raise LookupError(str(code if 400 <= code < 600 else 502))
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError('Response must be a JSON object.')
    return value
def identity(value, expected_moid, expected_type):
    if value.get('Moid') != expected_moid or value.get('ObjectType') != expected_type or value.get('ClassId') != expected_type:
        raise ValueError('Returned resource identity does not match the requested resource.')
def relation(value, expected_type):
    return isinstance(value, dict) and moid(value.get('Moid')) and value.get('ObjectType') == expected_type and value.get('ClassId') in (None, 'mo.MoRef', expected_type)
statusCode, statusMessage, errorMessage = '502', 'Firmware status lookup failed', ''
resultJson, route, statusUrl, resourceUrl = '{}', '', '', ''
upgradeMoid, upgradeType, statusMoid = '', '', ''
downloadStage, downloadPercentage, overallStatus, overallPercentage = '', '', '', ''
operationFailed, helperReady = False, False

statusMoid, upgradeMoid, upgradeType = sys.argv[1:4]
errors = []
if statusMoid and not moid(statusMoid):
    errors.append('Upgrade Status ID must be exactly 24 hexadecimal characters.')
if upgradeMoid and not moid(upgradeMoid):
    errors.append('Upgrade ID must be exactly 24 hexadecimal characters.')
if bool(upgradeMoid) != bool(upgradeType):
    errors.append('Provide Upgrade ID and Upgrade Resource Type together.')
if upgradeType and upgradeType not in COLLECTIONS:
    errors.append('Upgrade Resource Type must be firmware.Upgrade, firmware.ChassisUpgrade, or firmware.SwitchUpgrade.')
if not statusMoid and not upgradeMoid:
    errors.append('Provide Upgrade Status ID, or Upgrade ID and Upgrade Resource Type.')
route = 'error' if errors else 'status' if statusMoid else 'resource'
statusCode = '400' if errors else '200'
statusMessage = 'Invalid firmware status inputs' if errors else 'Firmware status lookup inputs validated'
errorMessage = ' '.join(errors)
statusUrl = '/api/v1/firmware/UpgradeStatuses/' + statusMoid if route == 'status' else ''
resourceUrl = '/api/v1/firmware/' + COLLECTIONS[upgradeType] + '/' + upgradeMoid if route == 'resource' else ''
resultJson = json.dumps({'status':'invalid-input' if errors else 'ready', 'errors':errors, 'monitoringPerformed':False}, separators=(',', ':'))
if errors:
    statusMoid = upgradeMoid = upgradeType = ''
helperReady = True

