    link = payload.get('UpgradeStatus')
    if link in (None, {}):
        route = 'pending'
        statusCode = '200'
        overallStatus = native_status
        operationFailed = native_status in ('FAILED', 'TERMINATED')
        errorMessage = 'Firmware upgrade reports ' + native_status + '.' if operationFailed else ''
        statusMessage = 'Firmware upgrade reports ' + native_status + '; detailed status is not available.'
