        resultJson = json.dumps({'status':'failed' if operationFailed else 'completed' if native_status == 'SUCCESSFUL' else 'pending', 'createdMoid':upgradeMoid, 'createdObjectType':upgradeType, 'upgradeStatusMoid':None, 'observedStatus':native_status, 'overallStatus':native_status, 'completed':native_status in ('SUCCESSFUL', 'FAILED', 'TERMINATED'), 'successful':True if native_status == 'SUCCESSFUL' else False if operationFailed else None, 'statusAvailable':False, 'monitoringPerformed':False}, separators=(',', ':'))
    else:
