import json
import re
import sys

COLLECTIONS = {'firmware.Upgrade':'Upgrades', 'firmware.ChassisUpgrade':'ChassisUpgrades', 'firmware.SwitchUpgrade':'SwitchUpgrades'}
def moid(value):
    return isinstance(value, str) and re.fullmatch('[0-9a-fA-F]{24}', value) is not None
def safe_text(value, maximum=500):
    if not isinstance(value, str) or len(value) > maximum or any(ord(c) < 32 for c in value):
        return ''
    if re.search(r'authorization|password|secret|token|api.?key|bearer|https?://', value, re.IGNORECASE):
        return ''
    return value
def envelope(raw, code, succeeded):
    code = int(code)
    if code != 200 or succeeded != 'true':
        raise LookupError(str(code if 400 <= code < 600 else 502))
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError('Response must be a JSON object.')
    return value
def identity(value, expected_moid, expected_type):
    if value.get('Moid') != expected_moid or value.get('ObjectType') != expected_type or value.get('ClassId') != expected_type:
        raise ValueError('Returned resource identity does not match the requested resource.')
def relation(value, expected_type):
    return isinstance(value, dict) and moid(value.get('Moid')) and value.get('ObjectType') == expected_type and value.get('ClassId') in (None, 'mo.MoRef', expected_type)
statusCode, statusMessage, errorMessage = '502', 'Firmware status lookup failed', ''
resultJson, route, statusUrl, resourceUrl = '{}', '', '', ''
upgradeMoid, upgradeType, statusMoid = '', '', ''
downloadStage, downloadPercentage, overallStatus, overallPercentage = '', '', '', ''
operationFailed, helperReady = False, False

statusMoid, upgradeMoid, upgradeType = sys.argv[4:7]
try:
    payload = envelope(sys.argv[1], sys.argv[2], sys.argv[3])
    identity(payload, statusMoid, 'firmware.UpgradeStatus')
    owner = payload.get('Upgrade')
    if owner not in (None, {}):
        owner_type = owner.get('ObjectType') if isinstance(owner, dict) else None
        if owner_type not in COLLECTIONS or not relation(owner, owner_type):
            raise ValueError('UpgradeStatus owner relationship is malformed.')
        if upgradeMoid and (owner['Moid'] != upgradeMoid or owner_type != upgradeType):
            raise ValueError('UpgradeStatus belongs to a different upgrade resource.')
        upgradeMoid, upgradeType = owner['Moid'], owner_type
    elif upgradeMoid and sys.argv[7] != 'resource':
        raise ValueError('UpgradeStatus does not confirm the requested upgrade relationship.')
    def percentage(key):
        value = payload.get(key)
        if value is None or value == -1 and type(value) is int:
            return ''
        if type(value) is not int or not 0 <= value <= 100:
            raise ValueError(key + ' must be an integer percentage or -1 for unknown.')
        return str(value)
    reported_download = percentage('DownloadPercentage')
    connector_download = percentage('DownloadProgress')
    downloadPercentage = reported_download or connector_download
    overallPercentage = percentage('OverallPercentage')
    raw_stage = payload.get('DownloadStage')
    if raw_stage is not None and (not isinstance(raw_stage, str) or len(raw_stage) > 128):
        raise ValueError('DownloadStage must be a bounded string.')
    downloadStage = safe_text(raw_stage, 128)
    raw_overall = payload.get('Overallstatus')
    if raw_overall is not None and (not isinstance(raw_overall, str) or len(raw_overall) > 128):
        raise ValueError('Overallstatus must be a bounded string.')
    overallStatus = safe_text(raw_overall, 128)
    errors = {}
    omitted = False
    for key in ('OverallError', 'DownloadError', 'SdCardDownloadError'):
        value = payload.get(key)
        if value is not None and not isinstance(value, str):
            raise ValueError(key + ' must be a string.')
        if value:
            clean = safe_text(value)
            omitted = omitted or not clean
            errors[key] = clean or 'Error detail omitted; inspect the Intersight upgrade.'
    normalized = overallStatus.lower()
    known = {'none', 'started', 'prepare initiating', 'prepare initiated', 'prepared', 'download initiating', 'download initiated', 'downloading', 'downloaded', 'upgrade initiating on fabric a', 'upgrade initiated on fabric a', 'upgrading fabric a', 'rebooting fabric a', 'upgraded fabric a', 'upgrade initiating on fabric b', 'upgrade initiated on fabric b', 'upgrading fabric b', 'rebooting fabric b', 'upgraded fabric b', 'upgrade initiating', 'upgrade initiated', 'upgrading', 'oob images staging', 'oob images staged', 'rebooting', 'upgraded', 'success', 'failed', 'terminated', 'pending', 'readyforcache', 'caching', 'cached', 'cachingfailed'}
    operationFailed = normalized in ('failed', 'terminated', 'cachingfailed') or bool(errors)
    finished = normalized in ('success', 'failed', 'terminated', 'cachingfailed')
    errorMessage = ' '.join(dict.fromkeys(errors.values()))
    if operationFailed and not errorMessage:
        errorMessage = 'Firmware upgrade reports ' + overallStatus + '.'
    statusCode = '200'
    route = 'snapshot'
    statusMessage = 'Firmware upgrade status: ' + (overallStatus or 'not reported') + '.'
    if downloadStage:
        statusMessage += ' Download stage: ' + downloadStage + '.'
    if downloadPercentage:
        statusMessage += ' Download: ' + downloadPercentage + '%.'
    if overallPercentage:
        statusMessage += ' Overall: ' + overallPercentage + '%.'
    resultJson = json.dumps({'status':'failed' if operationFailed else 'completed' if normalized == 'success' else 'unknown' if normalized in ('', 'none') or normalized not in known else 'in-progress', 'createdMoid':upgradeMoid or None, 'createdObjectType':upgradeType or None, 'upgradeStatusMoid':statusMoid, 'downloadStage':downloadStage or None, 'downloadPercentage':int(downloadPercentage) if downloadPercentage else None, 'overallStatus':overallStatus or None, 'overallPercentage':int(overallPercentage) if overallPercentage else None, 'errors':errors, 'errorDetailsOmitted':omitted, 'completed':finished, 'successful':True if normalized == 'success' and not operationFailed else False if operationFailed else None, 'statusAvailable':True, 'monitoringPerformed':False}, separators=(',', ':'))
except LookupError as exc:
    statusCode, errorMessage, route = str(exc), 'Upgrade status lookup failed. Verify the identifiers and read access on this Intersight endpoint.', 'error'
except (ValueError, TypeError, KeyError) as exc:
    errorMessage, route = str(exc), 'error'
if route == 'error':
    downloadStage = downloadPercentage = overallStatus = overallPercentage = ''
    resultJson = json.dumps({'status':'lookup-failed', 'message':errorMessage, 'createdMoid':upgradeMoid or None, 'createdObjectType':upgradeType or None, 'upgradeStatusMoid':statusMoid, 'monitoringPerformed':False}, separators=(',', ':'))
helperReady = True
